const root = document.getElementById("app");


  // Playback speed (prompter's slider). preservesPitch is the default in
  // modern engines but iOS wants the webkit-prefixed property set explicitly.
export function applyPlayRate(){
    [S.audio].concat(S._loopEls||[]).forEach(a=>{
      if(!a) return;
      try{ a.preservesPitch=true; a.webkitPreservesPitch=true; }catch(e){}
      try{ a.playbackRate=S.playRate||1; }catch(e){}
    });
    // a rate change moves the bar line's wall-clock arrival — re-aim the wrap
    if(S._loopEngine) loopSchedule(S._loopEngine);
  }

  // ── gapless practice loop v2 (Louis, 2026-08-08: « il faut que ce soit
  // nickel ») ──────────────────────────────────────────────────────────────
  // v1 had two audible latencies: ENGAGING swapped playback onto a cold
  // <audio> element (a full play() start-up), and every WRAP paid the
  // standby's play() start-up at the bar line. v2:
  //   * engaging keeps the MAIN element rolling — leg 1 rides S.audio, zero
  //     start-up; the ping-pong pair only enters at the first wrap;
  //   * ~150 ms before the bar line the standby starts MUTED, its clock
  //     aligned to cross `a` exactly when the active crosses `b`; the wrap
  //     itself is volume 1↔0 — no play(), no seek, on the boundary;
  //   * the standby's real start-up delay is measured at each crossover and
  //     fed back into the next arm (adaptive, clamped to 80 ms).
  // Boundary detection: a coarse setTimeout into a rAF spin — the engine
  // drives itself; callers no longer poll for the wrap.
  // The crossover moment is tunable BY EAR — Louis, same night: "encore un
  // poil trop tard". loopEpsS is how EARLY we cross (rAF detection alone can
  // be a frame late); the prompter shows an earlier/later adjuster while a
  // loop runs, persisted as harmLoopEpsMs. Default 12 ms early.
export const LOOP_PRE_S=0.15;
export let loopEpsS=(()=>{ const v=parseFloat(localStorage.getItem("harmLoopEpsMs")); return isFinite(v)?v/1000:0.012; })();
export function loopEpsSet(ms){
    loopEpsS=Math.max(-0.04, Math.min(0.08, ms/1000));
    try{ localStorage.setItem("harmLoopEpsMs", String(Math.round(loopEpsS*1000))); }catch(e){}
  }
export function ensureLoopEls(){
    const src=S._audioBlobUrl||S.audioUrl; if(!src) return null;
    if(!S._loopEls){
      const mk=()=>{ const el=new Audio(); el.preload="auto"; el.playsInline=true;
        try{ el.setAttribute("playsinline",""); el.setAttribute("webkit-playsinline",""); }catch(e){}
        return el; };
      S._loopEls=[mk(),mk()];
    }
    S._loopEls.forEach(el=>{ if(el._src!==src){ el.src=src; el._src=src; el.load(); } el.volume=1; });
    return S._loopEls;
  }
export function loopStandby(e){ return e.active===e.els[0] ? e.els[1] : e.els[0]; }
export function loopEngineStart(a,b){
    if(!S.audio || !ensureLoopEls()) return null;
    loopEngineDispose(false);
    applyPlayRate();
    const eng={a, b, els:S._loopEls, active:S.audio, playing:true,
               _timer:null, _raf:null, _lat:0.02};
    const pos=S.audio.currentTime;
    // leg 1 rides the MAIN element — only seek if we are outside the loop
    if(pos<a-0.05 || pos>b-0.05){ try{ S.audio.currentTime=a; }catch(e){} }
    S.playing=true;
    if(S.audio.paused) S.audio.play().catch(()=>{});
    S._loopEngine=eng;
    loopSchedule(eng);
    setPlayBtn();
    return eng;
  }
export function loopSchedule(eng){
    if(eng._timer){ clearTimeout(eng._timer); eng._timer=null; }
    if(eng._raf){ cancelAnimationFrame(eng._raf); eng._raf=null; }
    if(!eng.playing || S._loopEngine!==eng) return;
    const rate=S.playRate||1;
    const ms=Math.max(0, ((eng.b-eng.active.currentTime)/rate - LOOP_PRE_S)*1000);
    eng._timer=setTimeout(()=>loopArm(eng), ms);
  }
export function loopArm(eng){
    if(S._loopEngine!==eng || !eng.playing) return;
    const st=loopStandby(eng), rate=S.playRate||1;
    // align the standby's clock so it crosses `a` when the active crosses
    // `b`; _lat is the measured play() start-up of the previous wrap
    const rem=Math.max(0,(eng.b-eng.active.currentTime)/rate);
    try{ st.currentTime=Math.max(0, eng.a - rem*rate + eng._lat); }catch(e){}
    st.volume=0;
    st.play().catch(()=>{});
    const spin=()=>{
      if(S._loopEngine!==eng || !eng.playing){ try{ st.pause(); st.volume=1; }catch(e){} return; }
      if(eng.active.currentTime>=eng.b-loopEpsS){
        // measure how far the standby lagged its mark, feed the next arm
        const err=eng.a - st.currentTime;
        eng._lat=Math.max(0, Math.min(0.08, eng._lat + err*0.7));
        st.volume=1;
        const old=eng.active;
        try{ old.pause(); }catch(e){}
        if(old!==S.audio) old.volume=1;
        eng.active=st;
        loopSchedule(eng);
        return;
      }
      eng._raf=requestAnimationFrame(spin);
    };
    eng._raf=requestAnimationFrame(spin);
  }
export function loopEngineToggle(){
    const e=S._loopEngine; if(!e) return;
    e.playing=!e.playing; S.playing=e.playing;
    if(e.playing){ e.active.play().catch(()=>{}); loopSchedule(e); }
    else{
      e.active.pause();
      if(e._timer){ clearTimeout(e._timer); e._timer=null; }
      if(e._raf){ cancelAnimationFrame(e._raf); e._raf=null; }
      const st=loopStandby(e); try{ st.pause(); st.volume=1; }catch(err){}
    }
  }
export function loopEngineSeek(t){
    const e=S._loopEngine; if(!e) return;
    try{ e.active.currentTime=Math.max(e.a,Math.min(t,e.b-0.05)); }catch(err){}
    loopSchedule(e);
  }
export function loopEngineDispose(resume){
    const e=S._loopEngine; if(!e) return;
    S._loopEngine=null;
    if(e._timer) clearTimeout(e._timer);
    if(e._raf) cancelAnimationFrame(e._raf);
    const pos=e.active.currentTime, playing=e.playing;
    e.els.forEach(x=>{ try{ x.pause(); x.volume=1; }catch(err){} });
    if(e.active!==S.audio && S.audio){
      try{ S.audio.currentTime=pos; }catch(err){}
      if(resume!==false && playing && S.playing) S.audio.play().catch(()=>{});
    }
  }

