    S._coachGlyph.appendChild(glyph(ch.root,q,20,"exact",T.ink,(lv>=3)?ch.bass:-1));
    S._coachNames.textContent=m.map(x=>note(mod(x,12))).join(" · ")+(picked?"  ·  "+picked.style:"");
