    // only starts once the app is backgrounded (the audio session is released).
    // (1) A chord-preview / rotor-tick WebAudio AudioContext can hold the iOS
    // audio session so the HTMLMediaElement never gets it — SUSPEND them so the
    // element can take the session (they resume on the next chord/rotor tap).
    suspendPreviewAudio();
    try{ if(typeof tickCtx!=="undefined" && tickCtx && tickCtx.state==="running") tickCtx.suspend(); }catch(e){}
    S.playing=true; setPlayBtn();
